-- Run after database creation and sample-data insertion.
USE RestaurantSalesDB;
GO

-- =====================================================
-- 10. CUSTOMER-WISE SALES ANALYSIS
-- =====================================================

-- Calculate completed sales generated by each customer.

SELECT
    c.CustomerID,
    c.CustomerName,
    SUM(oi.Quantity * oi.UnitPrice) AS TotalSales
FROM Customers AS c
INNER JOIN Orders AS o
    ON c.CustomerID = o.CustomerID
INNER JOIN OrderItems AS oi
    ON o.OrderID = oi.OrderID
WHERE o.OrderStatus = 'Completed'
GROUP BY
    c.CustomerID,
    c.CustomerName
ORDER BY TotalSales DESC;

-- =====================================================
-- 11. CUSTOMER SALES ANALYSIS USING LEFT JOIN
-- =====================================================

-- Include all customers, even those without completed orders.
-- Display zero sales for customers without completed sales.

SELECT
    c.CustomerID,
    c.CustomerName,
    COALESCE(SUM(oi.Quantity * oi.UnitPrice), 0) AS TotalSales
FROM Customers AS c
LEFT JOIN Orders AS o
    ON c.CustomerID = o.CustomerID
    AND o.OrderStatus = 'Completed'
LEFT JOIN OrderItems AS oi
    ON o.OrderID = oi.OrderID
GROUP BY
    c.CustomerID,
    c.CustomerName
ORDER BY TotalSales DESC;

-- =====================================================
-- 12. PRODUCT-WISE SALES ANALYSIS
-- =====================================================

-- Calculate completed sales revenue and quantity sold
-- for each product.

SELECT
    p.ProductID,
    p.ProductName,
    p.Category,
    SUM(oi.Quantity) AS TotalQuantitySold,
    SUM(oi.Quantity * oi.UnitPrice) AS TotalRevenue
FROM Products AS p
INNER JOIN OrderItems AS oi
    ON p.ProductID = oi.ProductID
INNER JOIN Orders AS o
    ON oi.OrderID = o.OrderID
WHERE o.OrderStatus = 'Completed'
GROUP BY
    p.ProductID,
    p.ProductName,
    p.Category
ORDER BY TotalRevenue DESC;

-- =====================================================
-- 13. CATEGORY-WISE SALES ANALYSIS
-- =====================================================

-- Analyse completed sales across product categories.
-- Calculate order counts, quantities, average item value,
-- minimum and maximum unit prices, and total revenue.

SELECT
    p.Category,
    COUNT(DISTINCT o.OrderID) AS NumberOfOrders,
    SUM(oi.Quantity) AS TotalQuantitySold,
    AVG(oi.Quantity * oi.UnitPrice) AS AverageItemValue,
    MIN(oi.UnitPrice) AS MinimumUnitPrice,
    MAX(oi.UnitPrice) AS MaximumUnitPrice,
    SUM(oi.Quantity * oi.UnitPrice) AS TotalRevenue
FROM Products AS p
INNER JOIN OrderItems AS oi
    ON p.ProductID = oi.ProductID
INNER JOIN Orders AS o
    ON oi.OrderID = o.OrderID
WHERE o.OrderStatus = 'Completed'
GROUP BY p.Category
ORDER BY TotalRevenue DESC;

-- =====================================================
-- 14. ORDER STATUS ANALYSIS
-- =====================================================

-- Compare order counts and order values by status.
-- Include revenue only from completed orders.

SELECT
    o.OrderStatus,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    SUM(oi.Quantity * oi.UnitPrice) AS TotalOrderValue,
    SUM(
        CASE
            WHEN o.OrderStatus = 'Completed'
                THEN oi.Quantity * oi.UnitPrice
            ELSE 0
        END
    ) AS CompletedRevenue
FROM Orders AS o
INNER JOIN OrderItems AS oi
    ON o.OrderID = oi.OrderID
GROUP BY o.OrderStatus
ORDER BY TotalOrders DESC;
